"""Guide PDF120–123, visually checked with continuations and rating dots."""
import json,sys
from pathlib import Path
repo=Path(__file__).resolve().parent.parent;work=Path(sys.argv[1]);source=next(x for x in json.loads((work/'pages/manifest.json').read_text(encoding='utf-8')) if x['id']=='players-guide-v5')
rows=[
('famous-face','Rosto Famoso','Famous Face','merit',1,[120],True,
'Sua aparência lembra alguém muito conhecido. Recebe +2 dados em testes Sociais quando puder aproveitar essa semelhança, mas sofre −2 dados ao esconder-se em uma multidão ou em situações nas quais precisa evitar reconhecimento. A semelhança também pode levar terceiros a atribuir suas ações à pessoa famosa.',
'You resemble someone very well known. Gain +2 dice on Social tests when leveraging that resemblance, but take −2 dice when hiding in a crowd or otherwise trying to avoid recognition. Others may also attribute your actions to the famous person.'),
('ingenue','Aparência Inocente','Ingénue','merit',1,[120],True,
'Parece completamente inocente e isento de culpa, facilitando que acreditem em suas boas intenções. Recebe +2 dados em testes para evitar suspeitas ou desviar culpa, a critério do Narrador.',
'You look completely innocent and blameless, making others more likely to trust your intentions. Gain +2 dice on rolls to avoid suspicion or deflect blame, at the Storyteller’s discretion.'),
('remarkable-feature','Traço Marcante','Remarkable Feature','merit',1,[120],True,
'Possui uma característica rara e memorável, como cor dos olhos marcante, pupilas atípicas ou compleição incomum. Recebe +2 dados em interações Sociais com desconhecidos; a novidade rapidamente perde o efeito. Sofre −1 dado ao tentar disfarçar-se.',
'You have a rare, memorable feature, such as striking eye color, atypical pupils or an unusual complexion. Gain +2 dice on Social interactions with strangers; the novelty quickly wears off. Take −1 die when disguising yourself.'),
('vessel-recognition','Reconhecimento de Presas','Vessel Recognition','merit',1,[120,121],False,
'Aprendeu a reconhecer pelo cheiro presas usadas por outros vampiros, evitando alimentar-se inadvertidamente de seus Rebanhos ou Bonecos de Sangue. Um sucesso em Determinação + Percepção, Dificuldade 2, detecta se um mortal foi alvo de alimentação recentemente. Um sucesso crítico também revela se a alimentação é recorrente, sugerindo que pertence ao Rebanho de alguém.',
'You can smell vessels used by other vampires, helping avoid their Herds or Blood Dolls. A successful Resolve + Awareness test at Difficulty 2 detects whether a mortal has been fed on recently. A critical win also detects recurring feeding, suggesting membership in someone’s Herd.'),
('luck-of-the-devil','Sorte do Diabo','Luck of the Devil','merit',4,[121],True,
'Uma vez por sessão, pode fazer uma desgraça dirigida a você atingir outra pessoa próxima, desde que haja alguém disponível para recebê-la. Pode ser ataque, acusação, culpa ou outra desgraça adequada. A vítima pode ser Aliado, Lacaio, integrante da coterie ou até Pilar. O Narrador decide o que constitui uma desgraça apropriada. Usar repetidamente outras pessoas dessa forma pode destruir suas relações.',
'Once per session, redirect a misfortune aimed at you onto someone else close by, provided someone is available to take the fall. It may be an attack, accusation, blame or another appropriate misfortune. The victim can be an Ally, Retainer, coterie mate or even a Touchstone. The Storyteller decides what counts as a suitable misfortune. Repeatedly sacrificing others this way can destroy relationships.'),
('nuit-mode','Modo Nuit','Nuit Mode','merit',2,[121],False,
'Seu corpo não retorna automaticamente ao estado da morte a cada noite: pode manter novos cortes de cabelo, tatuagens e outras modificações corporais. Ainda pode retornar ao estado original, recuperando modificações posteriores como se fossem dano Agravado. Disponível somente para Membros com Potência de Sangue 1 ou menor. Se a Potência aumentar, a Qualidade deixa de produzir benefício; o benefício retorna caso volte a 1 ou menos. Não apague a escolha nem reembolse pontos automaticamente por essa mudança.',
'Your body does not automatically return to its death-state each night, allowing you to keep new haircuts, tattoos and other body modifications. You may still return to the original state, mending later modifications as if they were Aggravated damage. Available only to Kindred at Blood Potency 1 or lower. If Potency increases, the Merit grants no benefit; its benefit returns if Potency returns to 1 or lower. Do not automatically erase the choice or refund its dots when that changes.'),
('check-the-trunk','Confira o Porta-Malas','Check the Trunk','merit',1,[121],True,
'Tem fácil acesso a um arsenal ou estoque de ferramentas e equipamentos. Nenhum item pode exceder o valor disponível com Recursos 2; o Narrador aprova o conteúdo. Exemplos incluem arma de cano serrado, corta-vergalhões, fita adesiva, estacas caseiras e fluido de isqueiro. Acrescente 2 pontos às paradas de Preparação para encontrar itens dessa faixa de Recursos, conforme Livro Básico, p. 410. Perder carro, Refúgio ou outro depósito pode interromper o benefício até montar novo estoque.',
'You have easy access to an armory or cache of tools and hardware. No item may exceed what Resources 2 can provide; contents require Storyteller approval. Examples include a sawed-off shotgun, bolt cutters, duct tape, homemade stakes and lighter fluid. Add 2 dots to Preparedness pools for items within that Resource band, following Corebook p. 410. Losing the car, Haven or other storage may interrupt the benefit until a new cache is built.'),
('side-hustler','Fazedor de Bicos','Side Hustler','merit',2,[121,122],True,
'Uma vez por sessão, consegue um item, informação ou acesso a um evento como se tivesse 2 pontos no Antecedente apropriado: Recursos, Contatos ou Influência. Itens obtidos por Recursos provavelmente precisam ser devolvidos intactos. Frequentemente exige passar parte da noite cobrando favores e mobilizando sua rede informal. Não concede pontos permanentes nesses Antecedentes.',
'Once per session, obtain an item, information or access to an event as if you had 2 dots in the appropriate Resources, Contacts or Influence Background. Items obtained through Resources likely must be returned intact. This often takes part of the night calling in favors and mobilizing an informal network. It does not grant permanent dots in those Backgrounds.'),
('tempered-will','Vontade Temperada','Tempered Will','merit',3,[122],True,
'Sempre percebe quando Dominação ou Presença está sendo usada contra você. Uma vez por sessão, pode somar +2 dados à parada para resistir a uma dessas Disciplinas. Só pode adquirir a Qualidade se não tiver pontos em nenhuma delas. Se obtiver Dominação ou Presença posteriormente, mesmo de modo temporário como Sangue-Ralo, o benefício fica inativo enquanto possuir esses pontos. Perceber o uso não garante resistir ao efeito.',
'You always know when Dominate or Presence is being used against you. Once per session, add +2 dice to a pool resisting either Discipline. Only someone with no dots in either can acquire this Merit. If you later gain Dominate or Presence, even temporarily as a Thin-blood, its benefit is inactive while those dots are possessed. Awareness of use does not guarantee successful resistance.'),
('untouchable','Intocável','Untouchable','merit',5,[122],False,
'Uma vez por história, escapa de toda punição oficial por um crime que normalmente causaria sua destruição ou expulsão da seita. Ainda pode receber reprimenda privada ou consequências por canais não oficiais. A Corte ou Conselho frequentemente ignora delitos menores, mas Membros de menor posição podem agir por conta própria contra suas transgressões e impunidade. Defina com o Narrador a proteção política que explica esse privilégio.',
'Once per story, escape all official punishment for a crime that would normally lead to destruction or expulsion from your sect. Private reprimands and unofficial consequences may still occur. The Court or Council often ignores lesser crimes, but lower-ranking Kindred may act independently against your transgressions and impunity. Agree with the Storyteller what political protection explains the privilege.'),
('stench','Fedor','Stench','flaw',1,[122],False,
'Seu hálito e odor corporal são sobrenaturalmente repugnantes, lembrando túmulos abertos e carne podre. Perfume pode amenizar parcialmente o problema, mas cria outros inconvenientes. Sofre −1 dado em sedução e paradas Sociais semelhantes e −2 dados em Furtividade contra oponentes capazes de cheirá-lo, salvo se estiver a barlavento, conforme a exceção expressa no original.',
'Your breath and body odor are supernaturally foul, like open graves and rotting flesh. Cologne may partly mask it but creates other problems. Take −1 die on seduction and similar Social pools, and −2 dice on Stealth against opponents able to smell you, unless you are upwind, preserving the source’s stated exception.'),
('transparent','Transparente','Transparent','flaw',1,[122],True,
'Não mente bem: sua expressão ou necessidade de dizer a verdade o denuncia. Sofre −1 dado em qualquer parada que exija Subterfúgio e não pode adquirir pontos nessa Habilidade. A proibição de pontos não elimina a penalidade quando um teste de Subterfúgio ainda for exigido.',
'You are visibly poor at lying, whether through expression or a compulsion toward truthfulness. Take −1 die on any pool requiring Subterfuge and cannot gain dots in that Skill. The prohibition on dots does not remove the penalty when a Subterfuge test is still required.'),
('vein-tapper','Perfurador de Veias','Vein Tapper','flaw',1,[122],False,
'Considera a alimentação extremamente pessoal e não consegue beber sangue de mortais enquanto é observado. Por isso costuma alimentar-se de pessoas desavisadas e buscar ou provocar situações em que as vítimas estejam drogadas ou inconscientes. O Defeito trata da presença de observadores, não de uma preferência alimentar que acrescente pontos de Rebanho.',
'Feeding is intensely personal and you cannot take blood from mortals while being observed. You therefore often feed on the unaware and seek or create opportunities involving drugged or unconscious victims. The Flaw concerns observers; it does not grant Herd dots.'),
('starving-decay','Decomposição pela Fome','Starving Decay','flaw',2,[122],False,
'Quando a Fome chega a 3 ou mais, seu corpo resseca e se decompõe. Sofre −2 dados em testes Físicos e em interações Sociais com mortais, além de arriscar a Máscara. A condição é ligada à Fome atual, não a um gasto permanente de Humanidade.',
'At Hunger 3 or higher, your body shrivels and decays. Take −2 dice on Physical tests and Social interactions with mortals, also risking the Masquerade. The condition depends on current Hunger, not a permanent Humanity expenditure.'),
('twice-cursed','Duplamente Amaldiçoado','Twice-Cursed','flaw',2,[123,58,59,60,61],False,
'Recebe a Perdição alternativa do seu clã descrita no Guia, pp. 56–59, além da Perdição padrão. Não é uma substituição e não concede uma segunda Compulsão ou Disciplinas adicionais. O Narrador pode proibir este Defeito se a Perdição adicional não tiver impacto ou causar problemas na crônica. A ficha usa a variante correspondente ao clã; não é uma escolha livre entre as 14. Se a crônica já substitui a Perdição padrão por uma variante, a combinação requer revisão do Narrador antes de selecionar este Defeito.',
'Gain your clan’s variant Bane from Guide pp. 56–59 in addition to its regular Bane. This is not a replacement and does not add a second Compulsion or extra Disciplines. The Storyteller may prohibit this Flaw if the additional Bane lacks impact or causes problems. The character uses the variant matching the clan, not a free choice among all 14. If the chronicle already replaces the regular Bane with a variant, that combination requires Storyteller review before selecting this Flaw.'),
('knowledge-hungry','Faminto por Conhecimento','Knowledge Hungry','flaw',1,[123],True,
'Na criação, escolha um tema que deseja estudar obsessivamente. Ao encontrar livros, vídeos de instrução, seminários universitários ou outros meios de aprender sobre o tema, faça um teste de Vontade, Dificuldade 3, para resistir a perseguir essa obsessão e dedicar-se a tarefas mais urgentes.',
'At creation, choose a topic of obsessive study. When encountering books, tutorial videos, college seminars or other ways to learn about it, make a Willpower roll at Difficulty 3 to resist pursuing the obsession and instead attend to more urgent matters.'),
('prestation-debts','Dívidas de Favores','Prestation Debts','flaw',1,[123],False,
'Deve dois favores menores a um Membro ou a dois Membros com mais poder e influência que você na sociedade vampírica, embora não necessariamente na sua seita. Enquanto cobra a dívida, o credor recebe +1 dado em conflito Social contra você e pode exigir o pagamento a qualquer momento, geralmente inconveniente. Mesmo após quitar os dois favores, não precisa substituir este Defeito e o credor mantém o bônus de +1 dado. Pode ser adquirido junto a um ou mais Favores Menores na criação. Não pode dever esses favores ao personagem de outro jogador. Veja também Favores e Dívidas, Guia p. 115.',
'Owe two minor boons to one Kindred or two Kindred with more power and influence than you in vampire society, though not necessarily in your sect. A creditor gains +1 die in Social conflict against you while holding your marker and may demand repayment at any time, usually an inconvenient one. After both boons are repaid, no replacement Flaw is needed and the creditor retains the +1 die bonus. May coexist with one or more Minor Boons during creation. The boons cannot be owed to another player’s character. See also Boons and Debts, Guide p. 115.'),
('risk-taker','Amante do Risco','Risk-Taker','flaw',1,[123],True,
'Ao ser confrontado com a oportunidade de uma experiência arriscada que ainda não viveu, como usar uma droga nova, beber Sangue vampírico ou ter um amante Membro, sofre −2 dados em todas as ações até experimentar ou a cena terminar. Não obriga a realizar algo suicida, embora possa subestimar as consequências.',
'When faced with a risky temptation never experienced before, such as a new drug, vampire Blood or a Kindred lover, take −2 dice on all actions until you partake or the scene ends. It does not compel suicide, though you may underestimate the consequences.'),
('weak-willed','Vontade Fraca','Weak-Willed','flaw',2,[123],True,
'Tem dificuldade em afirmar a própria personalidade contra a vontade alheia; pode sentir-se mais seguro seguindo outra pessoa, sem ser necessariamente leal a ela. Sofre −1 dado em paradas Sociais contra seu líder ou superior. Mesmo percebendo tentativas de influenciá-lo mental ou emocionalmente, como Dominação ou Presença, não pode usar sistemas de resistência ativa para evitar esses efeitos.',
'You struggle to assert your personality against another’s will, perhaps feeling safer following someone without necessarily being loyal. Take −1 die on Social pools against your leader or superior. Even when aware of mental or emotional influence, such as Dominate or Presence, you cannot use active resistance systems to avoid those effects.')]
for slug,pt,en,kind,dots,numbers,universal,text,english in rows:
 id=f'guide-{kind}-{slug}';req={'characterTypes':['vampire','ghoul','mortal'] if universal else ['vampire']}
 if slug=='nuit-mode':req['maxBloodPotency']=1
 if slug=='tempered-will':req['forbiddenDisciplines']=['Dominação','Presença']
 if slug=='transparent':req['zeroSkills']=['Subterfúgio']
 if slug=='twice-cursed':req.update(clans=['Banu Haqim','Brujah','Gangrel','Hecata','Lasombra','Malkavian','Ministério','Nosferatu','Ravnos','Salubri','Toreador','Tremere','Tzimisce','Ventrue'],standardBaneOnly=True,storytellerApproval=True)
 prompts={'remarkable-feature':('Característica marcante','Memorable feature'),'knowledge-hungry':('Tema de estudo','Study topic'),'prestation-debts':('Credor(es) e favores — personagens do Narrador','Creditors and boons — Storyteller characters')}
 if slug in prompts:req.update(requiresDetail=True,detailLabel=dict(zip(['pt-BR','en'],prompts[slug])))
 pages=[{'pdfPage':n,'printedPage':n-2} for n in sorted(set(numbers))]
 rating_pt=f'{dots} ponto(s). '+(f'Qualidade: a escolha completa custa {dots*3} XP. ' if kind=='merit' else 'Defeito: não concede XP. ')
 rating_en=f'{dots} dot(s). '+(f'Merit: the full fixed-rated choice costs {dots*3} XP. ' if kind=='merit' else 'Flaw: does not grant XP. ')
 rating_pt+='Os efeitos de cena e limites por sessão/história são resolvidos manualmente com o Narrador.' if slug!='twice-cursed' else 'A Perdição adicional é registrada na ficha; consulte sua descrição para os efeitos aplicáveis.'
 rating_en+='Scene effects and per-session/story limits are resolved manually with the Storyteller.' if slug!='twice-cursed' else 'The additional Bane is recorded with the character; consult its description for applicable effects.'
 descriptions={'pt-BR':[{'title':'Sistema','text':text},{'title':'Valor e uso','text':rating_pt}],'en':[{'title':'System','text':english},{'title':'Rating and use','text':rating_en}]}
 entry={'id':id,'kind':kind,'names':{'pt-BR':pt,'en':en},'aliases':[pt,en],'level':dots,'versions':[{'id':id+'-players-guide-v5','book':'players-guide-v5','level':dots,'sourceTitle':'Player’s Guide V5, pp. '+', '.join(str(p['printedPage']) for p in pages),'sourceLanguage':'en','pdfSha256':source['sha256'],'pages':pages,'requirements':req,'descriptions':descriptions}]}
 (repo/'scripts/reviewed-content'/f'{id}.json').write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
id='guide-background-city-secrets'
pt='Um segredo comprometedor sobre o poder dos Membros da cidade, possivelmente sobre alguém específico. Defina-o com o Narrador. Um segredo apenas sobre negócios mortais explica Influência, não este Antecedente. Alguns poderosos sabem ou suspeitam que possui a informação; divulgar após seu desaparecimento pode protegê-lo. Pode vender a informação, mas quem deseja mantê-la secreta também pode decidir silenciá-lo. O Narrador decide quando acrescenta dados a uma parada Social, de Pesquisa ou de Sagacidade. Máximo de três escolhas, cada uma com segredo diferente.'
en='A damaging secret about the city’s Kindred power structure, possibly a specific person. Define it with the Storyteller. A secret concerning only mortal business explains Influence rather than this Background. Some powerful figures know or suspect you hold the information; arranging disclosure after disappearance may protect you. You may sell it, but those wanting secrecy may decide to silence you. The Storyteller decides when it adds to a Social, Research or Insight pool. Maximum three choices, each with a different secret.'
entry={'id':id,'kind':'background','names':{'pt-BR':'Segredos da Cidade','en':'City Secrets'},'aliases':['Segredos da Cidade','City Secrets'],'level':1,'versions':[{'id':id+'-players-guide-v5','book':'players-guide-v5','level':1,'sourceTitle':'Player’s Guide V5, p. 118','sourceLanguage':'en','pdfSha256':source['sha256'],'pages':[{'pdfPage':120,'printedPage':118}],'requirements':{'repeatableInstances':True,'differentDetails':True,'maxInstances':3,'detailLabel':{'pt-BR':'Segredo da cidade','en':'City secret'},'storytellerApproval':True},'descriptions':{locale:[{'title':'Sistema' if locale=='pt-BR' else 'System','text':pt if locale=='pt-BR' else en},{'title':'Valor' if locale=='pt-BR' else 'Rating','text':'1 ponto por segredo; máximo de três segredos diferentes. Cada compra custa 3 XP.' if locale=='pt-BR' else '1 dot per secret; maximum three different secrets. Each purchase costs 3 XP.'}] for locale in ['pt-BR','en']}}]}
(repo/'scripts/reviewed-content'/f'{id}.json').write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
print('20 Guide entries: 10 Merits, 9 Flaws and City Secrets; original pages, full bilingual mechanics and guided detail requirements.')
